/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rxt_rf_update (Boolean do_time_update)
{	
	rxt_ready_update () ;
	
	if(rxt.state == RXT_STATE_STARTED)
	{
		rf_icon_set  (ICON_SUCCESS, FALSE) ;
	}
	else
	{
		rf_icon_clr  (ICON_SUCCESS, FALSE) ;
	}

	if(do_time_update)
	{
		rf_icon_set  (ICON_TIME, FALSE) ;
	}
	rf_sound_set ((Rf_Sound_Def)rxt.runtime, TRUE)  ;

	os_tsk_wait  (20) ;
	rf_icon_clr  (ICON_TIME, FALSE) ;	
}

